using System.IdentityModel.Tokens.Jwt;
using System.Security.Claims;
using System.Text;
using Microsoft.Extensions.Options;
using Microsoft.IdentityModel.Tokens;
using RealtimeGateway.Configuration;

namespace RealtimeGateway.Security;

/// <summary>
/// Validates JWT tokens generated by AuthService.
/// </summary>
public class JwtTokenValidator : IJwtTokenValidator
{
    private readonly JwtOptions _jwtOptions;

    public JwtTokenValidator(IOptions<JwtOptions> jwtOptions)
    {
        _jwtOptions = jwtOptions.Value;
    }

    public AuthenticatedConnection? ValidateToken(string token)
    {
        var tokenHandler = new JwtSecurityTokenHandler();

        var validationParameters = new TokenValidationParameters
        {
            ValidateIssuer = true,
            ValidateAudience = true,
            ValidateLifetime = true,
            ValidateIssuerSigningKey = true,

            ValidIssuer = _jwtOptions.Issuer,
            ValidAudience = _jwtOptions.Audience,
            IssuerSigningKey = new SymmetricSecurityKey(
                Encoding.UTF8.GetBytes(_jwtOptions.Key)
            )
        };

        try
        {
            var principal = tokenHandler.ValidateToken(
                token,
                validationParameters,
                out _
            );

            var playerId = principal.FindFirst(ClaimTypes.NameIdentifier)?.Value;
            var username = principal.FindFirst(ClaimTypes.Name)?.Value;
            var role = principal.FindFirst(ClaimTypes.Role)?.Value;

            if (string.IsNullOrWhiteSpace(playerId))
            {
                return null;
            }

            return new AuthenticatedConnection
            {
                PlayerId = playerId,
                Username = username ?? string.Empty,
                Role = role ?? string.Empty
            };
        }
        catch
        {
            return null;
        }
    }
}